"""One-time author script for the Zain master-plan registries (kept outside the repo).
Writes ZMP backlog rows, gate edges, gates, journeys, risks, sources and capabilities.
V3 rows are then added by `zmp.py sync-v3`."""
import csv, io, sys
from pathlib import Path

ROOT = Path(sys.argv[1])  # docs/zain-master-plan
REG = ROOT / "registry"
REG.mkdir(parents=True, exist_ok=True)
sys.path.insert(0, str(ROOT / "tools"))
from zmp import SCHEMAS  # noqa: E402

def write(name, rows):
    hdr = SCHEMAS[name]
    out = io.StringIO()
    w = csv.DictWriter(out, fieldnames=hdr, lineterminator="\n")
    w.writeheader()
    for r in rows:
        missing = set(hdr) - set(r)
        extra = set(r) - set(hdr)
        assert not missing and not extra, (name, r.get(hdr[0]), missing, extra)
        w.writerow(r)
    (REG / name).write_text(out.getvalue(), encoding="utf-8")

def T(id, milestone, subsystem, owner, title, why, deps, deliverables, acceptance, tests, evidence, security,
      est, complexity, risk, tier, status="NOT_STARTED", status_evidence="", blockers="", group="", ref="", cost="FREE"):
    return dict(id=id, source="ZMP", milestone=milestone, phase="ZMP-" + milestone, subsystem=subsystem, owner=owner,
                title=title, why=why, deps=deps, deliverables=deliverables, acceptance=acceptance, tests=tests,
                evidence_required=evidence, security=security, est_pw=est, complexity=complexity, risk=risk, tier=tier,
                cost_class=cost, status=status, status_evidence=status_evidence, blockers=blockers,
                parallel_group=group, ref=ref)

